class Regression
{
    static readonly List<object> cases = new();
    static void Assert(bool condition,string message) { if (!condition) throw new Exception(message); }
    static void Equal(double? value,double expected) { Assert(value.HasValue && Math.Abs(value.Value - expected) < 0.0000001,"Expected "+expected+", got "+value); }
    static void Case(string name,Action action)
    {
        try { action(); cases.Add(new{name,passed=true}); Console.WriteLine("PASS "+name); }
        catch(Exception ex) { cases.Add(new{name,passed=false,error=ex.ToString()}); Console.WriteLine("FAIL "+name+": "+ex.Message); }
    }
    static RecordedProfilerSample S(int index,string name,int children,int descendants,double startMs,double durationMs,long? bytes=null)
    {
        return new RecordedProfilerSample { Index=index,Name=name,MarkerId=bytes.HasValue ? 99 : 2,
            Category="Scripts",CategoryId=1,Children=children,Descendants=descendants,StartNs=(ulong)(startMs*1000000),DurationNs=(ulong)(durationMs*1000000),
            IsGcAllocation=bytes.HasValue,GcBytes=bytes,GcMetadataStatus=bytes.HasValue ? "recorded" : null };
    }
    static RecordedProfilerThread Nested() => new()
    {
        FrameIndex=17,ThreadIndex=0,ThreadId=9007199254740993,ThreadName="Main Thread",ThreadGroup="",
        FrameDurationNs=10000000,DeclaredSampleCount=4,GcMarkerAvailable=true,
        Samples=new[]{S(0,"Parent",2,3,0,10),S(1,"ChildA",1,1,1,3),S(2,"Domain.Type::Method/Variant",0,0,2,1),S(3,"ChildB",0,0,5,2)}
    };
    static NativeThread Install(RecordedProfilerThread thread)
    {
        var native=new NativeThread{Header=thread,Samples=thread.Samples.Select(value=>new NativeSample{Value=value}).ToArray()};
        if(!ProfilerDriver.Frames.TryGetValue(thread.FrameIndex,out var list)) ProfilerDriver.Frames[thread.FrameIndex]=list=new();
        thread.ThreadIndex=list.Count;list.Add(native);return native;
    }
    static void Reset() { ProfilerDriver.Frames.Clear();ProfilerDriver.enabled=false;ProfilerDriver.profileEditor=false;ProfilerDriver.MutationCalls=0;ProfilerFrameDataIterator.Opened=ProfilerFrameDataIterator.Disposed=0; }
    static void Closed() { Assert(ProfilerDriver.Frames.Values.SelectMany(t=>t).All(t=>t.Opened==t.Disposed&&t.AccessAfterDispose==0),"Native view lifetime mismatch");Assert(ProfilerFrameDataIterator.Opened==ProfilerFrameDataIterator.Disposed,"Thread iterator leaked");Assert(ProfilerDriver.MutationCalls==0&&!ProfilerDriver.enabled&&!ProfilerDriver.profileEditor,"Reader mutated profiler state"); }
    static RecordedProfilerReadResult Read(RecordedProfilerReadOptions options=null,Func<bool> expired=null,Action cancelled=null) => RecordedProfilerFrameReader.Read(new UnityRecordedProfilerSource(),options??new(),expired,cancelled);
    static NativeThread Allocations(int count=1)
    {
        var t=Nested();t.DeclaredSampleCount=count;t.Samples=Enumerable.Range(0,count).Select(i=>S(i,"GC.Alloc",0,0,i,0,4096)).ToArray();return Install(t);
    }
    static void StackSchema(JToken token,JObject schema)
    {
        if(schema["anyOf"] is JArray choices){foreach(JObject choice in choices){try{StackSchema(token,choice);return;}catch{}}throw new Exception("No schema branch: "+token.Path);}
        if(schema["const"]!=null)Assert(JToken.DeepEquals(token,schema["const"]),"Const schema mismatch "+token.Path);
        if(schema["enum"] is JArray allowed)Assert(allowed.Any(item=>JToken.DeepEquals(item,token)),"Enum schema mismatch "+token.Path);
        if(token is JArray bounded && schema.Value<int?>("maxItems") is int maximum)Assert(bounded.Count<=maximum,"Array bound schema mismatch "+token.Path);
        if(schema["type"]!=null){var types=schema["type"] is JArray many?many.Values<string>().ToArray():new[]{schema.Value<string>("type")};var type=token.Type switch {JTokenType.Null=>"null",JTokenType.Object=>"object",JTokenType.Array=>"array",JTokenType.Integer=>"integer",JTokenType.Float=>"number",JTokenType.Boolean=>"boolean",_=>"string"};Assert(types.Contains(type)||type=="integer"&&types.Contains("number"),"Type schema mismatch "+token.Path);}
        if(token is JObject obj&&schema["properties"] is JObject props){foreach(var key in schema["required"]?.Values<string>()??Array.Empty<string>())Assert(obj.Property(key)!=null,"Missing schema field "+key);foreach(var prop in obj.Properties()){Assert(props.Property(prop.Name)!=null||schema.Value<bool?>("additionalProperties")!=false,"Unexpected schema field "+prop.Name);if(props[prop.Name] is JObject child)StackSchema(prop.Value,child);}}
        if(token is JArray array&&schema["items"] is JObject items)foreach(var item in array)StackSchema(item,items);
    }
