        RuntimeProfiler.FixtureStorage=args[1];
        Case("Nested physical tree uses direct children once",()=>{var a=RecordedProfilerFrameAnalysis.Analyze(Nested());Equal(a.Nodes[0].SelfTimeMs,5);Equal(a.Nodes[1].SelfTimeMs,2);Equal(a.Nodes[2].SelfTimeMs,1);Assert(a.Nodes[0].Children.SequenceEqual(new[]{1,3})&&a.Nodes[2].ParentIndex==1&&a.Nodes[3].Depth==1,"Wrong physical tree");});
        Case("Punctuation remains a single physical name",()=>{var a=RecordedProfilerFrameAnalysis.Analyze(Nested());Assert(a.Nodes.Length==4&&a.Nodes[2].Raw.Name=="Domain.Type::Method/Variant"&&a.Nodes[2].ParentIndex==1,"Synthetic path nodes introduced");});
        Case("Filters never alter self accounting",()=>{var a=RecordedProfilerFrameAnalysis.Analyze(Nested());var s=RecordedProfilerFrameAnalysis.Select(a,null,new[]{"ChildA"},null,0,10,RecordedProfilerSort.SelfTime);Equal(s.Single(n=>n.Raw.Name=="Parent").SelfTimeMs,5);Assert(s.Any(n=>n.ParentIndex==1),"Hidden parent changed real descendant identity");});
        Case("Multiple roots retain physical siblings",()=>{var t=Nested();t.Samples[0].Children=1;t.Samples[0].Descendants=2;var a=RecordedProfilerFrameAnalysis.Analyze(t);Assert(a.Nodes[3].ParentIndex==null&&a.Nodes[3].Depth==0,"Second root became descendant");});
