        Case("Zero duration remains measured zero",()=>{var t=Nested();t.DeclaredSampleCount=1;t.Samples=new[]{S(0,"Zero",0,0,0,0)};var a=RecordedProfilerFrameAnalysis.Analyze(t);Equal(a.Nodes[0].SelfTimeMs,0);Equal(a.Nodes[0].TotalTimeMs,0);});
        Case("Absolute nanoseconds above2^53 retain exact interval difference",()=>{var t=Nested();const ulong b=9007199254740993;t.DeclaredSampleCount=2;t.Samples=new[]{S(0,"Parent",1,1,0,10),S(1,"A",0,0,0,3)};t.Samples[0].StartNs=b;t.Samples[1].StartNs=b+1000000;Equal(RecordedProfilerFrameAnalysis.Analyze(t).Nodes[0].SelfTimeMs,7);});
